"use client"

import * as React from "react"
import { Terminal } from "@/components/ui/terminal"

/** The first frame lands mid run, with the first test files already reported. */
const FIRST_COUNT = 6

/** [delay before the line in ms, line] */
type Step = [number, string]

const E = "\u001b["

const gray = (s: string) => `${E}90m${s}${E}39m`

const green = (s: string) => `${E}32m${s}${E}39m`

const amber = (s: string) => `${E}33m${s}${E}39m`

const HEAD: Step[] = [
  [0, gray("> ledger@0.9.2 test /Users/mira/code/ledger")],
  [0, gray("> vitest run")],
  [0, ""],
  [420, ` ${E}1m${E}46m RUN ${E}49m${E}22m ${gray("/Users/mira/code/ledger")}`],
  [0, ""],
  [260, ` ${green("✓")} src/lib/money.test.ts ${gray("(14 tests)")} ${gray("12ms")}`],
