const FAIL_RUN: Step[] = [
  ...HEAD,
  [380, ` ${red("❯")} src/sync/upload.test.ts ${gray(`(6 tests | ${red("1 failed")})`)} ${gray("96ms")}`],
  [0, `   ${green("✓")} signs each request with the workspace key ${gray("4ms")}`],
