  [0, `   ${red("×")} retries a failed upload with backoff ${gray("61ms")}`],
  [0, `     ${red('→ expected "fetch" to be called 3 times, but got 2 times')}`],
  [340, ` ${green("✓")} src/ui/report.test.tsx ${gray("(21 tests)")} ${amber("318ms")}`],
  [220, ""],
  [0, red(`${RULE} ${bold("Failed Tests 1")} ${RULE}`)],
  [0, ""],
  [
    0,
    `${E}41m${E}1m FAIL ${E}22m${E}49m src/sync/upload.test.ts ${gray(">")} upload ${gray(">")} retries a failed upload with backoff`,
  ],
  [0, red(`${bold("AssertionError")}: expected "fetch" to be called 3 times, but got 2 times`)],
  [0, ` ${E}36m❯ src/sync/upload.test.ts:${dim("88:22")}${E}39m`],
  [0, `    ${gray(" 86|")}     await upload(receipt, { maxRetries: 2 })`],
  [0, `    ${gray(" 87|")}`],
  [0, `    ${red(bold(" 88|"))}     expect(fetchMock).toHaveBeenCalledTimes(3)`],
  [0, `    ${gray("   |")}                       ${red("^")}`],
  [0, `    ${gray(" 89|")}   })`],
  [0, ""],
  [200, ` ${dim("Test Files ")} ${bold(red("1 failed"))}${dim(" | ")}${bold(green("4 passed"))} ${gray("(5)")}`],
  [0, ` ${dim("     Tests ")} ${bold(red("1 failed"))}${dim(" | ")}${bold(green("87 passed"))} ${gray("(88)")}`],
  [0, ` ${dim("  Duration ")} 2.31s ${gray("(transform 412ms, collect 1.20s, tests 685ms)")}`],
  [0, ""],
  [180, `${E}41m${E}1m ELIFECYCLE ${E}22m${E}49m ${red("Test failed. See above for more details.")}`],
